using System.Collections.ObjectModel;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class DiscoverDatabasesViewModel:ObservableObject{readonly AgentDashboardClient c;bool busy,trust=true,verify=true;string host="localhost",port="1433",username="",password="",backup=@"D:\Backups\OdinVault",max="7",cron="",status="";public ObservableCollection<DiscoverRow> Items{get;}=[];public string Host{get=>host;set=>Set(ref host,value);}public string Port{get=>port;set=>Set(ref port,value);}public string Username{get=>username;set=>Set(ref username,value);}public string Password{get=>password;set=>Set(ref password,value);}public bool Trust{get=>trust;set=>Set(ref trust,value);}public string Backup{get=>backup;set=>Set(ref backup,value);}public string Max{get=>max;set=>Set(ref max,value);}public bool Verify{get=>verify;set=>Set(ref verify,value);}public string Cron{get=>cron;set=>Set(ref cron,value);}public string Status{get=>status;private set=>Set(ref status,value);}public bool Busy{get=>busy;private set=>Set(ref busy,value);}public DiscoverDatabasesViewModel(AgentDashboardClient x)=>c=x;int? PortValue=>int.TryParse(Port,out var p)&&p is>0 and<=65535?p:null;int MaxValue=>int.TryParse(Max,out var n)&&n>0?n:7;string? Null(string s)=>string.IsNullOrWhiteSpace(s)?null:s.Trim();public async Task DiscoverAsync(){if(string.IsNullOrWhiteSpace(Host)){Status="آدرس SQL Server را وارد کنید.";return;}Busy=true;Status="در حال شناسایی دیتابیس‌ها…";try{var rows=await c.DiscoverAsync(new(Host.Trim(),PortValue,Null(Username),Null(Password),Trust))??[];Items.Clear();foreach(var x in rows)Items.Add(new(x,x.CanBackup&&!x.IsRegistered));Status=rows.Count==0?"هیچ دیتابیسی پیدا نشد.":$"{rows.Count} دیتابیس پیدا شد.";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}public async Task AddSelectedAsync(){var selected=Items.Where(x=>x.Selected&&x.Item.CanBackup&&!x.Item.IsRegistered).ToList();if(selected.Count==0){Status="حداقل یک دیتابیس آماده بکاپ را انتخاب کنید.";return;}if(string.IsNullOrWhiteSpace(Backup)){Status="مسیر بکاپ را وارد کنید.";return;}Busy=true;var ok=0;var errors=new List<string>();try{foreach(var row in selected)try{var d=row.Item;var created=await c.CreateDatabaseAsync(new(d.Name,Host.Trim(),PortValue,d.Name,Null(Username),Null(Password),Trust,Backup.Trim(),MaxValue,Verify,Null(Cron),true));if(created is not null){await c.TestDatabaseAsync(created.Id);ok++;}}catch(Exception e){errors.Add($"{row.Item.Name}: {e.Message}");}Status=$"{ok} دیتابیس با موفقیت اضافه شد."+(errors.Count==0?"":"\n"+string.Join("\n",errors));await DiscoverAsync();}finally{Busy=false;}}}internal sealed class DiscoverRow:ObservableObject{bool selected;public DiscoveredDatabaseResponse Item{get;}public bool Selected{get=>selected;set=>Set(ref selected,value);}public string Name=>Item.Name;public string State=>Item.State;public string Recovery=>Item.RecoveryModel;public string Access=>Item.HasAccess?"دارد":"ندارد";public string Ready=>Item.CanBackup?"آماده":Item.IsSystem?"سیستمی":"خیر";public string Registered=>Item.IsRegistered?"بله":"خیر";public DiscoverRow(DiscoveredDatabaseResponse x,bool s){Item=x;selected=s;}}